import sys

def max_digit_sum(x):
    x_str = str(x)
    n = len(x_str)

    # Initialize the dp table
    dp = [[-1] * (n + 1) for _ in range(10 * n + 1)]
    dp[0][0] = 0

    # Fill the dp table
    for i in range(1, 10 * n + 1):
        for j in range(1, n + 1):
            for d in range(10):
                if i - d >= 0 and dp[i - d][j - 1] != -1:
                    dp[i][j] = max(dp[i][j], dp[i - d][j - 1] * 10 + d)

    # Find the maximum sum of digits that can be formed without exceeding x
    max_sum = 0
    for i in range(10 * n + 1):
        if dp[i][n] != -1 and dp[i][n] <= x:
            max_sum = i

    # Reconstruct the number with the maximum sum of digits
    result = []
    current_sum = max_sum
    for j in range(n, 0, -1):
        for d in range(9, -1, -1):
            if current_sum - d >= 0 and dp[current_sum - d][j - 1] == dp[current_sum][j] // 10:
                result.append(str(d))
                current_sum -= d
                break

    return int(''.join(result))

